/// Sequence `Build Doc String` — Concatenates the header parts and the body to produce the final delimited text..
Future<String> buildDocString({ts.Ref<String>? seqDocString}) async {
  final seqDocStringRef = seqDocString ?? ts.Ref<String>('');

  String stdHeader = ''; // Str
  String parametersHeader = ''; // Str

  final run = ts.SequenceRun();
  dynamic createParameterSHeaderResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of Create Parameter's Header

  stdHeader =
      'Sequence File' +
      fileGlobals.SEPARATOR +
      'Sequence' +
      fileGlobals.SEPARATOR +
      'Step Group' +
      fileGlobals.SEPARATOR +
      'Step Index' +
      fileGlobals.SEPARATOR +
      'Indent Level' +
      fileGlobals.SEPARATOR +
      'Step' +
      fileGlobals.SEPARATOR +
      'Icon' +
      fileGlobals.SEPARATOR +
      'Descirption' +
      fileGlobals.SEPARATOR +
      'Settings' +
      fileGlobals.SEPARATOR +
      'Requirement[0]' +
      fileGlobals.SEPARATOR; // Populate Standard Header
  // step loop (Custom): init RunState.LoopIndex = 0; while RunState.LoopIndex < FileGlobals.LargestParameterCount; increment RunState.LoopIndex += 1; status RunState.LoopNumPassed / RunState.LoopNumIterations < 1 ? "Failed" : "Passed"
  final loop = ts.StepLoop();
  loop.index = 0; // loop initialize
  while (loop.index < fileGlobals.LargestParameterCount) {
    // loop while
    createParameterSHeaderResult = ts.PropObj({
      'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
      'Status': '',
      'ReportText': '',
      'Common': ts.PropObj(),
    });
    parametersHeader =
        parametersHeader +
        'Parameter[' +
        ts.str(loop.index) +
        '] Name' +
        fileGlobals.SEPARATOR +
        'Parameter[' +
        ts.str(loop.index) +
        '] Value' +
        fileGlobals.SEPARATOR; // Create Parameter's Header
    createParameterSHeaderResult.Status = 'Done';
    loop.count(createParameterSHeaderResult.Status);
    loop.index += 1; // loop increment
  }
  createParameterSHeaderResult.Status = loop.numPassed / loop.numIterations < 1
      ? 'Failed'
      : 'Passed'; // loop status
  run.record(createParameterSHeaderResult.Status);
  ts.eval(
    'Locals.ParametersHeader = Trim(Locals.ParametersHeader, FileGlobals.SEPARATOR)',
  ); // Remove the Last Separator
  seqDocStringRef.value =
      stdHeader +
      parametersHeader +
      '\n' +
      seqDocStringRef.value; // Add Header To Steps Doc String

  return run.status;
}

/// Sequence `Get SubSequence Parameters` — Extracts parameters of a SubSequence call and return them as a tab-separated string..
Future<String> getSubSequenceParameters({
  ts.Ref<int>? numberOfParameters,
  dynamic currentStep,
  ts.Ref<String>? parametersList,
}) async {
  final numberOfParametersRef = numberOfParameters ?? ts.Ref<int>(0);
  final parametersListRef = parametersList ?? ts.Ref<String>('');

  dynamic currentParameter = null; // Ref
  int x = 0; // Num — default: 0

  final run = ts.SequenceRun();

  body:
  try {
    // ── main ──
    for (
      x = 0;
      x < currentStep.TS.SData.ActualArgs.GetNumSubProperties('');
      x += 1
    ) {
      currentParameter = currentStep.TS.SData.ActualArgs.GetNthSubProperty(
        '',
        x,
        0,
      ); // Retrieve Parameter
      parametersListRef.value =
          parametersListRef.value +
          currentParameter.Name +
          fileGlobals.SEPARATOR +
          currentParameter.Expr +
          fileGlobals.SEPARATOR; // Parse SubSequence Parameters
    }
  } finally {
    // ── cleanup ──
    numberOfParametersRef.value =
        ++x; // Set the Number of Parameters in the Module
  }

  return run.status;
}

/// Sequence `Get LabVIEW Module Parameters` — Extracts parameters of a LabVIEW Code Module and return them as a tab-separated string..
Future<String> getLabViewModuleParameters({
  ts.Ref<int>? numberOfParameters,
  dynamic currentStep,
  ts.Ref<String>? parametersList,
}) async {
  final numberOfParametersRef = numberOfParameters ?? ts.Ref<int>(0);
  final parametersListRef = parametersList ?? ts.Ref<String>('');

  int x = 0; // Num — default: 0
  dynamic currentParameter = null; // Ref

  final run = ts.SequenceRun();

  body:
  try {
    // ── main ──
    for (final element in ts.iterate(currentStep.TS.SData.ViCall.Parms)) {
      currentParameter = element;
      parametersListRef.value =
          parametersListRef.value +
          currentParameter.Label +
          fileGlobals.SEPARATOR +
          currentParameter.ArgVal +
          fileGlobals.SEPARATOR; // Parse Module Parameters
    }
  } finally {
    // ── cleanup ──
    numberOfParametersRef.value =
        ++x; // Set the Number of Parameters in the Module
  }

  return run.status;
}

